class Solution {
public:
    int firstCompleteIndex(vector<int>& arr, vector<vector<int>>& mat) {
        int m = mat.size();
        int n = mat[0].size();
        int total = m * n;
        vector<pair<int,int>> pos(total + 1);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                pos[mat[i][j]] = {i, j};
            }
        }
        vector<int> rowCount(m, 0);
        vector<int> colCount(n, 0);
        for (int i = 0; i < total; i++) {
            auto [r, c] = pos[arr[i]];
            rowCount[r]++;
            colCount[c]++;
            if (rowCount[r] == n || colCount[c] == m) {
                return i;
            }
        }
        return -1;
    }
};
